window.HOEREN_TESTS[69] = {"id":"bei-der-versicherung","name":"Bei der Versicherung","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Guten Tag, hier ist Ihre Versicherung. Wir haben Ihren Schaden geprüft. Gute Nachricht: Wir zahlen nicht die volle Summe, sondern 80 Prozent. Den Rest tragen Sie selbst, das ist die Selbstbeteiligung. Das Geld kommt nächste Woche auf Ihr Konto. Bei Fragen rufen Sie an!","gender":"f","q":"Wie viel zahlt die Versicherung?","opts":["80 Prozent.","Die volle Summe.","Gar nichts."],"correct":0},{"transcript":"Hallo Tom, hier ist Markus. Mein Fahrrad wurde gestohlen! Direkt vor dem Bahnhof, trotz Schloss. Ich hatte keinen Unfall, und mein Auto ist auch nicht kaputt. Zum Glück habe ich eine Versicherung. Aber ich muss es bei der Polizei melden, sonst zahlt die Versicherung nicht. Weißt du, wie das geht? Ruf mich an!","gender":"m","q":"Was ist mit Markus passiert?","opts":["Sein Auto ist kaputt.","Er hatte einen Unfall.","Sein Fahrrad wurde gestohlen."],"correct":2},{"transcript":"Achtung Kunden: Ab Januar ändern sich unsere Tarife. Die Hausratversicherung wird etwas teurer, aber die Leistungen sind besser. Neu versichert sind jetzt auch Fahrräder und Handys, nicht Autos und nicht Möbel extra. Wer den alten Tarif behalten will, melde sich bis Dezember. Sonst gilt automatisch der neue Tarif. Danke!","gender":"m","q":"Was ist ab Januar neu versichert?","opts":["Autos.","Fahrräder und Handys.","Möbel."],"correct":1},{"transcript":"Hi Lisa, hier ist Anna. Hey, ich überlege, eine Reiseversicherung abzuschließen, bevor ich nach Asien fliege. Keine Autoversicherung und keine Hausratversicherung. Falls ich krank werde, ist das im Ausland teuer. Mein Berater sagt, sie kostet nur 30 Euro für die ganze Reise. Findest du das sinnvoll? Sag mir deine Meinung!","gender":"f","q":"Welche Versicherung möchte Anna abschließen?","opts":["Eine Reiseversicherung.","Eine Autoversicherung.","Eine Hausratversicherung."],"correct":0},{"transcript":"Liebe Kunden: Unser Büro ist umgezogen. Sie finden uns jetzt nicht mehr in der Bahnhofstraße und nicht bei der Post im Gebäude, sondern in der Gartenstraße 12, direkt neben der Post. Die Telefonnummer und die Öffnungszeiten bleiben gleich. Termine bitte weiterhin vorher vereinbaren. Wir freuen uns auf Ihren Besuch!","gender":"f","q":"Wo ist das Büro jetzt?","opts":["In der Bahnhofstraße.","Bei der Post im Gebäude.","In der Gartenstraße."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer braucht welche Versicherung? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Die Beraterin hat um drei Zeit für unsere ganze Familie."},{"speaker":"Lisa","gender":"f","text":"Schön, dass der Termin feststeht. Ich will die Lücken endlich schließen."},{"speaker":"Lukas","gender":"m","text":"Ich brauche eine Autoversicherung. Der neue Wagen steht nachts auf der Straße."},{"speaker":"Lisa","gender":"f","text":"Für die Wohnung nehme ich eine Hausratversicherung. Dort steht schon viel teure Technik."},{"speaker":"Lukas","gender":"m","text":"Will jemand von uns noch eine Lebensversicherung?"},{"speaker":"Lisa","gender":"f","text":"Nein. Eine Lebensversicherung brauchen wir im Moment nicht."},{"speaker":"Lukas","gender":"m","text":"Tom fliegt im August für zwei Wochen in den warmen Süden."},{"speaker":"Lisa","gender":"f","text":"Tom schließt eine Reiseversicherung ab. Der Koffer und die Tickets liegen schon bereit."},{"speaker":"Lukas","gender":"m","text":"Sara fängt bald eine neue Stelle im Krankenhaus an."},{"speaker":"Lisa","gender":"f","text":"Sara meldet sich für eine Krankenversicherung an. Die neue Karte fehlt noch bei ihr."},{"speaker":"Lukas","gender":"m","text":"Braucht jemand eine Tierversicherung für ein Haustier?"},{"speaker":"Lisa","gender":"f","text":"Nein. Eine Tierversicherung nehmen wir nicht. Dafür reicht unser Geld kaum aus."},{"speaker":"Lukas","gender":"m","text":"Tim hat letzte Woche im Hausflur einen Spiegel kaputt gemacht."},{"speaker":"Lisa","gender":"f","text":"Tim holt sich eine Haftpflichtversicherung. Solche Schäden zahlt dann der Vertrag."},{"speaker":"Lukas","gender":"m","text":"Dann nennen wir der Beraterin genau diese fünf Punkte."},{"speaker":"Lisa","gender":"f","text":"Ich lege unsere Papiere ordentlich in die graue Mappe."}],"options":[{"letter":"a","text":"Krankenversicherung"},{"letter":"b","text":"Autoversicherung"},{"letter":"c","text":"Hausratversicherung"},{"letter":"d","text":"Rentenversicherung"},{"letter":"e","text":"Lebensversicherung"},{"letter":"f","text":"Reiseversicherung"},{"letter":"g","text":"Tierversicherung"},{"letter":"h","text":"Rechtsschutzversicherung"},{"letter":"i","text":"Haftpflichtversicherung"}],"items":[{"person":"Lukas","correct":"b"},{"person":"Lisa","correct":"c"},{"person":"Tom","correct":"f"},{"person":"Sara","correct":"a"},{"person":"Tim","correct":"i"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, was kostet die Versicherung im Monat? 40 Euro?"},{"speaker":"Berater","gender":"m","text":"Nicht 40 Euro. Der Basis-Tarif kostet 15 Euro."},{"speaker":"Kundin","gender":"f","text":"Und mit mehr Leistung?"},{"speaker":"Berater","gender":"m","text":"Dann 25 Euro im Monat. Also 15 Euro Basis, 25 Euro mit mehr Leistung, nicht 40."},{"speaker":"Kundin","gender":"f","text":"Dann nehme ich den Basis-Tarif für 15 Euro. Das reicht mir erstmal. Danke."}],"q":"Was kostet der Basis-Tarif?","opts":["15 Euro.","25 Euro.","40 Euro."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Guten Tag, ich möchte einen Schaden melden. Soll ich zur Polizei gehen oder das Rohr selbst reparieren?"},{"speaker":"Beraterin","gender":"f","text":"Was ist passiert? Gehen Sie nicht zuerst selbst reparieren."},{"speaker":"Mann","gender":"m","text":"Ein Wasserrohr ist geplatzt. Zur Polizei muss ich nicht, oder?"},{"speaker":"Beraterin","gender":"f","text":"Nein, nicht zur Polizei. Machen Sie bitte Fotos von dem Schaden, dann können wir zahlen."},{"speaker":"Mann","gender":"m","text":"Gut, ich mache Fotos und repariere nicht selbst. Danke."}],"q":"Was soll der Mann machen?","opts":["Zur Polizei gehen.","Fotos vom Schaden machen.","Das Rohr selbst reparieren."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, wie kann ich kündigen? Nur per Brief oder nur persönlich?"},{"speaker":"Berater","gender":"m","text":"Schriftlich, drei Monate vorher. Nicht nur persönlich."},{"speaker":"Frau","gender":"f","text":"Geht auch per E-Mail, oder muss ich einen Brief schicken?"},{"speaker":"Berater","gender":"m","text":"Ja, eine E-Mail reicht. Nicht nur per Brief, E-Mail ist okay."},{"speaker":"Frau","gender":"f","text":"Super, dann kündige ich per E-Mail. Danke."}],"q":"Wie kann die Frau kündigen?","opts":["Per E-Mail.","Nur per Brief.","Nur persönlich."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, wie hoch ist die Selbstbeteiligung? 50 Euro oder 300 Euro?"},{"speaker":"Beraterin","gender":"f","text":"Weder 50 Euro noch 300 Euro. Die Selbstbeteiligung ist 150 Euro pro Schaden."},{"speaker":"Kunde","gender":"m","text":"Geht das auch ohne Selbstbeteiligung?"},{"speaker":"Beraterin","gender":"f","text":"Ja, ohne geht, aber dann ist der Beitrag höher. Standard sind 150 Euro."},{"speaker":"Kunde","gender":"m","text":"Dann bleibe ich bei 150 Euro Selbstbeteiligung. Danke für die Info."}],"q":"Wie hoch ist die Selbstbeteiligung?","opts":["50 Euro.","300 Euro.","150 Euro."],"correct":2},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, wann bekomme ich mein Geld? In zwei Tagen oder in zwei Monaten?"},{"speaker":"Berater","gender":"m","text":"Sobald wir alle Unterlagen haben. Zwei Tage sind zu schnell, zwei Monate zu lang."},{"speaker":"Kundin","gender":"f","text":"Und das dauert wie lange ungefähr?"},{"speaker":"Berater","gender":"m","text":"Etwa zwei Wochen, wenn die Papiere vollständig sind."},{"speaker":"Kundin","gender":"f","text":"Okay, zwei Wochen. Ich schicke die Unterlagen heute. Danke."}],"q":"Wie lange dauert die Zahlung?","opts":["Zwei Tage.","Zwei Monate.","Zwei Wochen."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Richter, einer Versicherungsberaterin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Richter, welche Versicherung braucht man wirklich im Alltag?"},{"speaker":"Richter","gender":"f","text":"Nicht so viele. Wichtig ist eine Versicherung für Schäden, die Haftpflicht. Sie kostet wenig und hilft viel, wenn etwas kaputtgeht. Diese Versicherung braucht wirklich jeder, finde ich."},{"speaker":"Reporter","gender":"m","text":"Haben die Leute oft zu viele Versicherungen?"},{"speaker":"Richter","gender":"f","text":"Ja, leider. Manche haben fünf oder sechs. Viele brauchen sie gar nicht. Sie zahlen jeden Monat, aber der Schutz bringt ihnen nichts. Das ist schade ums Geld."},{"speaker":"Reporter","gender":"m","text":"Was ist der häufigste Fehler der Kunden?"},{"speaker":"Richter","gender":"f","text":"Die Leute lesen den Vertrag nicht. Dann sind sie überrascht, wenn etwas nicht bezahlt wird. Ich sage immer: Lesen Sie den Vertrag, bevor Sie unterschreiben."},{"speaker":"Reporter","gender":"m","text":"Soll man die Versicherung oft wechseln, jedes Jahr?"},{"speaker":"Richter","gender":"f","text":"Nicht jedes Jahr. Aber man soll die Preise ab und zu vergleichen. Manchmal spart man so 50 Euro im Jahr, ohne schlechteren Schutz."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie jungen Leuten?"},{"speaker":"Richter","gender":"f","text":"Fangen Sie einfach an und denken Sie früh an später. Aber kaufen Sie nicht zu viel. Ein paar gute Versicherungen sind besser als viele unnötige. Qualität ist wirklich wichtiger als die Menge."}],"items":[{"q":"Frau Richter findet eine Versicherung für Schäden wichtig.","correct":"ja"},{"q":"Sie meint, viele Leute haben zu viele Versicherungen.","correct":"ja"},{"q":"Sie sagt, man soll den Vertrag nicht lesen.","correct":"nein"},{"q":"Sie rät, die Preise ab und zu zu vergleichen.","correct":"ja"},{"q":"Sie meint, junge Leute sollen so viel wie möglich kaufen.","correct":"nein"}]}]};
